import type { FreeformCity } from "../freeformCity";
import type { Point } from "../primitives";
import type { CurveAnchor } from "./document";
import type { VectorPolygon } from "./generation";

export const VECTOR_FEATURE_KINDS = [
  "castle",
  "bastion",
  "harbor",
  "market",
  "temple",
  "cemetery",
  "park",
  "farm",
  "forest"
] as const;
export type VectorFeatureKind = (typeof VECTOR_FEATURE_KINDS)[number];
/** Persisted metre geometry, never regenerated by a renderer. */
export interface VectorFeature {
  id: string;
  kind: VectorFeatureKind;
  boundary: VectorPolygon;
  access: CurveAnchor;
  entrance: Point;
  connector: Point[];
  waterAnchor?: CurveAnchor;
  pathIds: string[];
  placementIds: string[];
  pieces: {
    id: string;
    role: "ground" | "structure" | "vegetation" | "quay" | "ship" | "cargo" | "stall";
    polygon: VectorPolygon;
    heightMeters: number;
    color: string;
  }[];
  settings: {
    density: number;
    heightMeters: number;
    activity: "market-day" | "closed";
    culture: "stone" | "timber";
    moatWidthMeters: number;
  };
  editPolicy: "fixed" | "editable";
}
export interface VectorEnvironment {
  features: Record<string, VectorFeature>;
  /** Freeform's authored ledger is the height/earthwork authority, not a synthetic cell mesh. */
  terrain?: FreeformCity;
  freeformSource?: FreeformCity;
  hidden: string[];
}
